    Bug 1969859 - Port bug 1055085: Fix Escape closing customization palette when clearing search. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D252192

diff --git a/mail/base/content/widgets/search-bar.mjs b/mail/base/content/widgets/search-bar.mjs
index ac0dc8e2f2d..a9d01c640d4 100644
--- a/mail/base/content/widgets/search-bar.mjs
+++ b/mail/base/content/widgets/search-bar.mjs
@@ -122,7 +122,7 @@ export class SearchBar extends HTMLElement {
     template.querySelector("slot[name=placeholder]").textContent =
       this.getAttribute("placeholder");
     this.#input.addEventListener("input", this);
-    this.#input.addEventListener("keyup", this);
+    this.#input.addEventListener("keydown", this);

     const styles = document.createElement("link");
     styles.setAttribute("rel", "stylesheet");
@@ -167,7 +167,7 @@ export class SearchBar extends HTMLElement {
         this.reset();
         this.focus();
         break;
-      case "keyup":
+      case "keydown":
         if (event.key === "Escape" && this.#input.value) {
           this.reset();
           event.preventDefault();
diff --git a/mail/components/unifiedtoolbar/content/unified-toolbar-customization.mjs b/mail/components/unifiedtoolbar/content/unified-toolbar-customization.mjs
index b7f64b3b8b8..6a84313dd5e 100644
--- a/mail/components/unifiedtoolbar/content/unified-toolbar-customization.mjs
+++ b/mail/components/unifiedtoolbar/content/unified-toolbar-customization.mjs
@@ -107,11 +107,13 @@ class UnifiedToolbarCustomization extends HTMLElement {
     switch (event.type) {
       case "keyup":
         this.#handleKeyboard(event);
-        this.#closeByKeyboard(event);
         break;
       case "keypress":
       case "keydown":
         this.#handleKeyboard(event);
+        if (event.type === "keydown") {
+          this.#closeByKeyboard(event);
+        }
         break;
     }
   }
